syntax:
template<typename T = DefaultType> class TemplateClassName { /* members */ };
// Usage with default: TemplateClassName<> instance;  // Empty brackets are required to instantiate with defaults
// Usage with specified type: TemplateClassName<SpecifiedType> instance2;
Practical usage notes: Always include the <> even for defaults to ensure portability and clarity. This pattern is idiomatic in C++ for maintaining type safety and enabling generic code without unnecessary verbosity.

code_example:
#include <iostream>

template<typename T = int>
class SimpleContainer {
private:
    T value;
public:
    SimpleContainer(T val) : value(val) {}
    void display() const {
        std::cout << "Value: " << value << std::endl;
    }
};

int main() {
    SimpleContainer<> defaultInstance(42);  // Using default argument (int)
    defaultInstance.display();  // Outputs: Value: 42

    SimpleContainer<double> specifiedInstance(3.14);  // Specifying double
    specifiedInstance.display();  // Outputs: Value: 3.14

    return 0;
}
